endpoint.request:
employment?: {
  ...invariato SENZA is_manager (chiave rimossa: se inviata viene ignorata dalla validazione),
  managed_business_function_ids?: int[] | null   // assente o null = invariato; [] = nessuna funzione gestita; distinct, exists:business_functions,id
}

endpoint.response:
data: User {
  ...invariato,
  managed_business_functions: [{ id: int, name: string }],   // invariato (0275), ordinate per name
  employment?: { ...invariato SENZA is_manager }
}
